                if j > 0:
                    dp[i][j] = (dp[i][j] + dp[i-1][j-1]) % MOD
                if j < i:
                    dp[i][j] = (dp[i][j] * 0) % MOD
                    if j >= 0:
                        dp[i][j] = (dp[i][j] + dp[i][j]) % MOD
